// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint56 changeFeeParam, uint16 feeRateParam, uint128 vb, uint128 vn) public {
        vm.assume(vn > 0);
        bound(feeRateParam, 0, 5000);

        c.initialize(
            address(0),
            address(0),
            vb,
            vn,
            changeFeeParam,
            feeRateParam,
            bytes32(0),
            false,
            false
        );

        // General rule: a native-base-token pool's flash fee equals changeFee * 10^14,
        // i.e. the change fee supplied at initialization is honored in derived quotes.
        assertTrue(c.flashFee(address(0), 0) == uint256(changeFeeParam) * 1e14);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint56 changeFee, uint16 feeRate, uint128 inputAmount) public {
        // Admissible domain: feeRate must satisfy the contract's own bound; keep changeFee/inputAmount
        // wide but safe from overflow in the expected-fee computation.
        vm.assume(feeRate <= 5_000);
        vm.assume(changeFee != 0);
        vm.assume(uint256(changeFee) <= 1e40);
        uint256 amt = bound(uint256(inputAmount), 1, 1e18);

        c.initialize(
            address(0),
            address(this),
            1_000e18,
            1_000e18,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 feeAmount, ) = c.changeFeeQuote(amt);

        uint256 expectedFee = amt * uint256(changeFee) * 1e14 / 1e18;
        assertTrue(feeAmount == expectedFee);
    }
}
